<?php use Simit\Core\Csrf; $canContribute=in_array($task['status'],['Tersedia','Dikerjakan','Tertunda'],true); ?>
<div class="result-grid"><section class="panel"><p class="eyebrow"><?=e($task['number'])?></p><h2><?=e($task['title'])?></h2><p class="muted"><?=e($task['description']??'')?></p><dl class="detail-list"><div><dt><?=__('Status','Status')?></dt><dd><span class="badge"><?=e(__($task['status']))?></span></dd></div><div><dt><?=__('PIC','Assignee')?></dt><dd><?=__('Tugas bersama — semua user dapat membantu.','Shared task — all users can help.')?></dd></div></dl><h3><?=__('Kontributor','Contributors')?></h3><div class="contributor-list"><?php foreach($contributions as $c):?><article><span class="avatar"><?=e(strtoupper(substr($c['user_name'],0,1)))?></span><div><strong><?=e($c['user_name'])?></strong><small><?=e($c['created_at'])?><?=!empty($c['is_final'])?' · '.__('Pengajuan final','Final submission'):''?></small><p><?=nl2br(e($c['body']))?></p></div></article><?php endforeach;?><?php if(!$contributions):?><div class="empty"><?=__('Belum ada kontribusi.','No contributions yet.')?></div><?php endif;?></div></section><?php if($canContribute):?><form class="panel stack" method="post" enctype="multipart/form-data"><?=Csrf::field()?><label><?=__('Kontribusi / bantuan','Contribution / assistance')?> *<textarea name="result" rows="8" required placeholder="<?=__('Jelaskan bantuan atau progres yang dikerjakan...','Describe the help or progress completed...')?>"></textarea></label><label><?=__('Lampiran bukti','Evidence attachment')?><input type="file" name="attachment" accept=".jpg,.jpeg,.png,.pdf"><small class="field-help">JPG, PNG, PDF · <?=__('Maks. 10 MB','Max. 10 MB')?></small></label><label class="check"><input type="checkbox" name="final_submission" value="1"><span><?=__('Ajukan sebagai hasil final untuk ACC Admin','Submit as final result for Admin approval')?></span></label><button class="btn primary"><?=__('Simpan kontribusi','Save contribution')?></button></form><?php endif;?></div><section class="panel attachment-panel"><div class="panel-head"><div><h3><?=__('Lampiran','Attachments')?></h3><p><?=__('Bukti bantuan tersimpan secara privat.','Assistance evidence is stored privately.')?></p></div></div><?php foreach($attachments as $a):?><a class="attachment-row" href="/lampiran/<?=$a['id']?>"><span class="file-icon">↓</span><div><strong><?=e($a['original_name'])?></strong><small><?=e($a['uploader'])?> · <?=number_format($a['size_bytes']/1024,1)?> KB</small></div></a><?php endforeach;?><?php if(!$attachments):?><div class="empty"><?=__('Belum ada lampiran.','No attachments yet.')?></div><?php endif;?></section>
